WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, SHEET_NAME, COLUMN_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, SMALL_CLASS_LABEL_NAME, LARGE_CLASS_LABEL_NAME, DEFAULT_FLAG, USER_SELECTABLE_FLAG, DIVISION_ID, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, INPUT_TP_CD) VALUES (s.PROGRAM_ID, s.SHEET_NAME, s.COLUMN_NAME, s.COLUMN_LABEL_NAME, s.SORT_ORDER_NO, s.SMALL_CLASS_LABEL_NAME, s.LARGE_CLASS_LABEL_NAME, s.DEFAULT_FLAG, s.USER_SELECTABLE_FLAG, s.DIVISION_ID, s.VALID_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE, s.ATTRIBUTE1, s.ATTRIBUTE2, s.ATTRIBUTE3, s.ATTRIBUTE4, s.ATTRIBUTE5, s.ATTRIBUTE6, s.ATTRIBUTE7, s.ATTRIBUTE8, s.ATTRIBUTE9, s.ATTRIBUTE10, s.INPUT_TP_CD);


